const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const thailand = ee.FeatureCollection("USDOS/LSIB_SIMPLE/2017").filter(ee.Filter.eq('country_na', 'Thailand')).geometry();
    const startDateFeb = '2008-02-01';
    const endDateFeb = '2008-02-29';
    const startDateAug = '2008-08-01';
    const endDateAug = '2008-08-31';

    // 2. Data Acquisition & Check
    const dataset = ee.ImageCollection('MODIS/061/MOD14A1').select('MaxFRP');

    const fireFeb = dataset.filterDate(startDateFeb, endDateFeb);
    const fireAug = dataset.filterDate(startDateAug, endDateAug);

    const febSize = fireFeb.size().getInfo();
    const augSize = fireAug.size().getInfo();

    if (febSize === 0 || augSize === 0) {
        console.log(`Image collection size February 2008: ${febSize}`);
        console.log(`Image collection size August 2008: ${augSize}`);
        console.log("No images found for one or both periods.");
        console.log("C1");
        return;
    }

    // 3. Processing
    // Create monthly composites by summing the Fire Radiative Power (FRP)
    const totalFRFeb = fireFeb.sum();
    const totalFRPAug = fireAug.sum();

    // 4. Calculation
    // Use a large scale for country-level analysis to avoid timeouts.
    const scale = 3000;

    const febFRPStats = totalFRFeb.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: thailand,
        scale: scale,
        maxPixels: 1e9
    });

    const augFRPStats = totalFRPAug.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: thailand,
        scale: scale,
        maxPixels: 1e9
    });

    const febFRPTotal = ee.Number(febFRPStats.get('MaxFRP')).getInfo();
    const augFRPTotal = ee.Number(augFRPStats.get('MaxFRP')).getInfo();

    // 5. Validation & Final Answer
    if (febFRPTotal === null || augFRPTotal === null) {
        console.log("Calculation failed, result is null.");
        console.log("C3");
        return;
    }

    console.log(`Total Fire Radiative Power (FRP) in February 2008: ${febFRPTotal.toFixed(2)}`);
    console.log(`Total Fire Radiative Power (FRP) in August 2008: ${augFRPTotal.toFixed(2)}`);

    if (augFRPTotal > febFRPTotal) {
        console.log("B");
    } else {
        console.log("A");
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error("An error occurred:", err);
    console.log("D");
});
